    {
      "n": "#254·22",
      "text": "A brown blazer with structured shoulders and a tailored waist, crafted from rich fabric that holds its shape beautifully. It features three front buttons, notched lapels, and two flap pockets for subtle detail."
    },
    {
      "n": "#187·26",
      "text": "A navy dress made of soft ribbed viscose, sleeveless with a scoop neckline trimmed in light blue piping. It falls to mid-calf length and hugs the body without restriction."
    },
    {
      "n": "#147·09",
      "text": "Black mules with a pointed toe and open back, accented by a sheer mesh upper printed with delicate cherry blossoms and hearts. The interior sole carries the same whimsical pattern for playful charm."
    },
    {
      "n": "#87·31",
      "text": "A grey suede clutch with a fold-over flap closure secured by a tan leather strap and circular gold-toned metal hardware featuring a floral emblem. Its matte finish adds quiet elegance."
    },
    {
      "n": "#330·27",
      "text": "A camel wool coat with wide lapels, front button closure, two large patch pockets, and a matching waist belt that can be tied or left open. The fabric has a soft texture and falls to mid-calf length."
    }
  ]
